export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: Incident };

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Incident = {
  cause: string;
  damages: Damage[];
};

export type Damage = {
  itemType: string;
  amount: number;
};

export type Result = { premium: number } | { payout: number; remainingCap: number };

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  return undefined as unknown as { results: Result[] };
};

