import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office — quote", () => {
  // Simplest case
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result.results).toEqual([{ premium: 5 }]);
  });

  // Base premiums per item type (with first insurance surcharge + fee)
  it("a single sword → base premium 100 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    // 100 base + 10 first insurance + 5 fee
    expect(result.results).toEqual([{ premium: 115 }]);
  });
  it("a single amulet → base premium 60 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });

    // 60 base + 6 first insurance + 5 fee
    expect(result.results).toEqual([{ premium: 71 }]);
  });
  it.todo("a single staff → base premium 80 G");
  it.todo("a single potion → base premium 40 G");
  it.todo("a single rune (component) → base premium 25 G");
  it.todo("a single moonstone (component) → base premium 25 G");

  // Building block of 3 alike components
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");

  // "Alike" components means exactly the same type
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // Item-specific modifiers
  it.todo("cursed sword → 50 % risk surcharge on that item's base premium");
  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply");

  // Policy-wide modifiers
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first quote in a scenario → 10 % first insurance surcharge on the policy base");
  it.todo("second quote in a scenario → 15 % follow-up contract discount");
  it.todo("first insurance surcharge still applies on a follow-up contract");

  // Modifier scope on multi-item policies
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (of the cursed item only) → 210 G before further modifiers and fee",
  );

  // Rounding
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");

  // Integration examples
  it.todo(
    "newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G",
  );
  it.todo(
    "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
  );
});

describe("MHPCO Claim Office — claim", () => {
  // Standard reimbursement
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");

  // Special clauses
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
  it.todo(
    "dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)",
  );
  it.todo(
    "dragon-material sword, exactly enchantment 8, damage 1000 G → payout 400 G (50 % rule applies, then deductible)",
  );
  it.todo(
    "dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)",
  );

  // Deductible per damage event
  it.todo(
    "one incident damaging an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)",
  );

  // Insurance sum and cap
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo(
    "a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)",
  );
  it.todo("a cursed sword → cap 2000 G (based on the unmodified insurance value)");

  // Cap exhaustion across successive claims
  it.todo(
    "sword policy (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G with remaining cap 600 G",
  );
  it.todo("second of the two successive 1500 G claims → payout 600 G, remaining cap 0 G");

  // Multiple items of the same type
  it.todo(
    "two insured swords, two sword damage entries → each entry is a separate damage with its own deductible",
  );

  // Rounding
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
});

describe("MHPCO Claim Office — errors", () => {
  it.todo("quote with an unknown item type (e.g. broomstick) → error");
  it.todo("claim damaging an item that is not part of the policy (amulet when only a sword is insured) → error");
  it.todo("claim damaging an item of unknown type → error");
  it.todo("claim with more damage entries of a type than the policy covers → error");
  it.todo("claim with a damage entry of amount -200 → error");
});

describe("MHPCO Claim Office — CLI", () => {
  it.todo("reads a scenario from stdin and writes { results } to stdout in step order");
  it.todo("schema example: amulet quote then a 200 G amulet claim → premium and payout/remainingCap");
  it.todo("exits with a non-zero status code and writes to stderr on an invalid scenario, with no results on stdout");
});

