export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: Incident };

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Incident = {
  cause: string;
  damages: Damage[];
};

export type Damage = {
  itemType: string;
  amount: number;
};

export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const formsABuildingBlock = (alikeItems: Item[]): boolean =>
  alikeItems.length === BLOCK_SIZE;

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const typesOf = (items: Item[]): string[] => [...new Set(items.map((item) => item.type))];

const groupedByType = (items: Item[]): Item[][] =>
  typesOf(items).map((type) => items.filter((item) => item.type === type));

const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);

const policyBaseOf = (items: Item[]): number =>
  groupedByType(items).reduce((sum, group) => sum + basePremiumOfAlikeItems(group), 0);

// Rounding always favours the MHPCO: premiums up, payouts down.
const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const firstInsuranceSurchargeOn = (policyBase: number): number =>
  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;

const quoteFor = (items: Item[]): Result => {
  const policyBase = policyBaseOf(items);
  return {
    premium: premiumRoundedInMHPCOsFavour(
      policyBase + firstInsuranceSurchargeOn(policyBase) + PROCESSING_FEE,
    ),
  };
};

const resultFor = (step: Step): Result => {
  if (step.op === "quote") return quoteFor(step.items);
  throw new Error(`unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map(resultFor),
});

