export type Customer = { yearsWithMHPCO: number };

export type Scenario = {
  customer: Customer;
  steps: Step[];
};

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: Incident };

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Incident = {
  cause: string;
  damages: Damage[];
};

export type Damage = {
  itemType: string;
  amount: number;
};

export type Result = { premium: number } | { payout: number; remainingCap: number };

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const formsABuildingBlock = (alikeItems: Item[]): boolean =>
  alikeItems.length === BLOCK_SIZE;

const sumOfBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const isCursed = (item: Item): boolean => item.cursed === true;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

// Every item-specific surcharge is a rate on THAT item's base premium, charged
// when its risk applies. Adding a new one means adding a row here — nothing else.
type ItemSurcharge = { appliesTo: (item: Item) => boolean; rate: number };

const ITEM_SURCHARGES: ItemSurcharge[] = [
  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
];

const surchargeRateOn = (item: Item): number =>
  ITEM_SURCHARGES.reduce(
    (rate, surcharge) => (surcharge.appliesTo(item) ? rate + surcharge.rate : rate),
    0,
  );

const itemSurchargesOn = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);

// Items of the same type are "alike"; each group is priced together so a
// building block can be recognised.
const alikeItemGroupsIn = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];

const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);

const policyBaseOf = (items: Item[]): number =>
  alikeItemGroupsIn(items).reduce(
    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
    0,
  );

// Rounding always favours the MHPCO: premiums up, payouts down.
const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_RATE = -0.2;

// Every quote so far is a first insurance: nothing in a Scenario yet distinguishes
// a follow-up contract. When the follow-up-discount tests arrive this has to consult
// the scenario's history, not the customer — hence the deliberate `always`.
const isAlwaysAFirstInsuranceForNow = (): boolean => true;

const isLongStanding = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS;

// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
// base that already includes the item surcharges. Surcharges carry a positive
// rate, discounts a negative one. Adding a new one means adding a row here.
type PolicyModifier = { appliesTo: (customer: Customer) => boolean; rate: number };

const POLICY_MODIFIERS: PolicyModifier[] = [
  { appliesTo: isAlwaysAFirstInsuranceForNow, rate: FIRST_INSURANCE_SURCHARGE_RATE },
  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
];

const policyModifierRateFor = (customer: Customer): number =>
  POLICY_MODIFIERS.reduce(
    (rate, modifier) => (modifier.appliesTo(customer) ? rate + modifier.rate : rate),
    0,
  );

const policyModifiersOn = (policyBase: number, customer: Customer): number =>
  policyBase * policyModifierRateFor(customer);

const quoteFor = (items: Item[], customer: Customer): Result => {
  const policyBase = policyBaseOf(items);
  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
  return {
    premium: premiumRoundedInMHPCOsFavour(
      riskAdjustedBase + policyModifiersOn(policyBase, customer) + PROCESSING_FEE,
    ),
  };
};

const resultFor = (step: Step, customer: Customer): Result => {
  if (step.op === "quote") return quoteFor(step.items, customer);
  throw new Error(`unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map((step) => resultFor(step, scenario.customer)),
});

